SELECT d.d_year, w.w_state, COUNT(DISTINCT i.i_item_sk) AS distinct_items, SUM(inv.inv_quantity_on_hand) AS total_quantity, (SELECT i2.i_current_price FROM item i2 WHERE i2.i_brand = 'importoscholar #2                                 ' LIMIT 1) AS price_for_brand FROM inventory inv JOIN date_dim d ON inv.inv_date_sk = d.d_date_sk JOIN item i ON inv.inv_item_sk = i.i_item_sk JOIN warehouse w ON inv.inv_warehouse_sk = w.w_warehouse_sk WHERE d.d_year = 1905 AND w.w_state = 'LA' GROUP BY d.d_year, w.w_state HAVING SUM(inv.inv_quantity_on_hand) > 834
